prompt --application/pages/page_00002
begin
wwv_flow_imp_page.create_page(
 p_id=>2
,p_name=>'Download page Using JS'
,p_alias=>'DOWNLOAD-PAGE-USING-JS'
,p_step_title=>'Download page Using JS'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/************************ CDN **********************************/',
'',
'-- --  PDF',
'-- https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.2.7/pdfmake.min.js',
'-- https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.2.7/vfs_fonts.js',
'-- https://cdn.jsdelivr.net/npm/html-to-pdfmake@2.5.5/browser.js',
'',
'',
'-- -- WORD',
'',
'-- https://cdnjs.cloudflare.com/ajax/libs/FileSaver.js/2.0.5/FileSaver.min.js',
'-- https://cdn.jsdelivr.net/npm/html-docx-js@0.3.1/dist/html-docx.min.js',
'',
'',
'',
'/************************ Static File **********************************/',
'',
'--  PDF',
'#APP_FILES#pdfmake.min.js',
'#APP_FILES#vfs_fonts.js',
'#APP_FILES#browser.js',
'',
'',
'-- WORD',
'',
'#APP_FILES#FileSaver.min.js',
'#APP_FILES#html-docx.min.js',
''))
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/**',
' * Master Rich Text Export Function for Oracle APEX',
' * Dynamically handles PDF, Word (.docx), and HTML file exports based on Page Item selection.',
' * ',
' * @param {string} [outputTypeItemName=''P2_OUTPUT_TYPE''] - Item name containing output format (''PDF'', ''WORD'', ''HTML'')',
' * @param {string} [htmlItemName=''P2_TEMPLATE_HTML'']     - Item name containing Rich Text HTML content',
' * @param {string} [fileNameItemName=''P2_FILE_NAME'']     - Item name containing target File Name',
' */',
'function exportRichTextDocument(outputTypeItemName, htmlItemName, fileNameItemName) {',
'    // 1. Assign Default Page Item Names if parameters are omitted',
'    outputTypeItemName = outputTypeItemName || ''P2_OUTPUT_TYPE'';',
'    htmlItemName       = htmlItemName       || ''P2_TEMPLATE_HTML'';',
'    fileNameItemName   = fileNameItemName   || ''P2_FILE_NAME'';',
'',
'    // 2. Fetch Values from APEX Page Items',
'    var outputType     = apex.item(outputTypeItemName).getValue();',
'    var htmlContent    = apex.item(htmlItemName).getValue();',
'    var customFileName = apex.item(fileNameItemName).getValue();',
'',
'    // Clear previous page error messages',
'    apex.message.clearErrors();',
'',
'    // 3. Validation: Check if Output Type is selected',
'    if (!outputType || outputType.trim() === "") {',
'        apex.message.showErrors([{',
'            type:     "error",',
'            location: "page",',
'            message:  "Please select an Output Type (PDF, WORD, or HTML).",',
'            unsafe:   false',
'        }]);',
'        return;',
'    }',
'',
'    // 4. Validation: Check if Rich Text Content is empty',
'    if (!htmlContent || htmlContent.trim() === "") {',
'        apex.message.showErrors([{',
'            type:     "error",',
'            location: "page",',
'            message:  "Rich Text Editor is empty. Please enter text before exporting.",',
'            unsafe:   false',
'        }]);',
'        return;',
'    }',
'',
'    // 5. Remove template block tags like {#employee}, {/employee}, {#dept}, etc.',
'    htmlContent = htmlContent.replace(/\{[\s]*[#\/][^}]*\}/g, "");',
'',
'    // 6. Sanitize and Format Default File Name',
'    if (!customFileName || customFileName.trim() === "") {',
'        customFileName = ''Document_'' + new Date().toISOString().slice(0, 10);',
'    } else {',
'        customFileName = customFileName.trim();',
'    }',
'',
'    // Remove existing common extensions to prevent double extensions (e.g., file.pdf.docx)',
'    customFileName = customFileName.replace(/\.(pdf|docx|html|htm|pptx)$/i, "");',
'',
'    // Normalize format string to uppercase',
'    var format = outputType.trim().toUpperCase();',
'',
'    try {',
'        if (format === ''PDF'') {',
'            // Validate required libraries for PDF Export',
'            if (typeof htmlToPdfmake === ''undefined'' || typeof pdfMake === ''undefined'') {',
'                apex.message.showErrors([{',
'                    type:     "error",',
'                    location: "page",',
'                    message:  "PDF generation libraries are not loaded. Please verify static files.",',
'                    unsafe:   false',
'                }]);',
'                return;',
'            }',
'',
'            customFileName += ''.pdf'';',
'',
'            // Convert HTML structure to pdfMake JSON format',
'            var pdfContent = htmlToPdfmake(htmlContent, {',
'                defaultStyles: {',
'                    b: { bold: true },',
'                    strong: { bold: true },',
'                    u: { decoration: ''underline'' },',
'                    s: { decoration: ''lineThrough'' },',
'                    i: { italics: true },',
'                    em: { italics: true }',
'                }',
'            });',
'',
'            var docDefinition = {',
'                content: pdfContent,',
'                pageMargins: [40, 60, 40, 60],',
'                defaultStyle: {',
'                    fontSize: 11,',
'                    font: ''Roboto''',
'                }',
'            };',
'',
'            // Download PDF Document',
'            pdfMake.createPdf(docDefinition).download(customFileName);',
'',
'        } else if (format === ''WORD'' || format === ''DOCX'') {',
'            // Validate required libraries for Word Export',
'            if (typeof htmlDocx === ''undefined'' || typeof saveAs === ''undefined'') {',
'                apex.message.showErrors([{',
'                    type:     "error",',
'                    location: "page",',
'                    message:  "Word export libraries are not loaded. Please verify static files.",',
'                    unsafe:   false',
'                }]);',
'                return;',
'            }',
'',
'            customFileName += ''.docx'';',
'',
'            // Wrap Rich Text HTML with document styling',
'            var fullHTML = `<!DOCTYPE html>',
'            <html>',
'            <head>',
'                <meta charset="utf-8">',
'                <style>',
'                    body { font-family: ''Calibri'', ''Arial'', sans-serif; font-size: 11pt; line-height: 1.5; }',
'                    table { border-collapse: collapse; width: 100%; margin-bottom: 10px; }',
'                    table, th, td { border: 1px solid #cccccc; padding: 6px; }',
'                    th { background-color: #f2f2f2; font-weight: bold; }',
'                    b, strong { font-weight: bold; }',
'                    i, em { font-style: italic; }',
'                    u { text-decoration: underline; }',
'                </style>',
'            </head>',
'            <body>',
'                ${htmlContent}',
'            </body>',
'            </html>`;',
'',
'            // Convert HTML to Docx Blob',
'            var convertedBlob = htmlDocx.asBlob(fullHTML, {',
'                orientation: ''portrait'',',
'                margins: { top: 720, right: 720, bottom: 720, left: 720 }',
'            });',
'',
'            // Download Word Document',
'            saveAs(convertedBlob, customFileName);',
'',
'        } else if (format === ''HTML'') {',
'            customFileName += ''.html'';',
'',
'            // Full standalone HTML Document template',
'            var fullHTMLDocument = `<!DOCTYPE html>',
'            <html lang="en">',
'            <head>',
'                <meta charset="UTF-8">',
'                <meta name="viewport" content="width=device-width, initial-scale=1.0">',
'                <title>Exported Document</title>',
'                <style>',
'                    body {',
'                        font-family: Arial, Helvetica, sans-serif;',
'                        line-height: 1.6;',
'                        color: #333333;',
'                        padding: 30px;',
'                        max-width: 900px;',
'                        margin: 0 auto;',
'                        background-color: #ffffff;',
'                    }',
'                    table {',
'                        border-collapse: collapse;',
'                        width: 100%;',
'                        margin: 15px 0;',
'                    }',
'                    table, th, td {',
'                        border: 1px solid #cccccc;',
'                    }',
'                    th, td {',
'                        padding: 10px;',
'                        text-align: left;',
'                    }',
'                    th {',
'                        background-color: #f4f6f8;',
'                        font-weight: bold;',
'                    }',
'                    img {',
'                        max-width: 100%;',
'                        height: auto;',
'                    }',
'                </style>',
'            </head>',
'            <body>',
'                ${htmlContent}',
'            </body>',
'            </html>`;',
'',
'            // Native browser download using Blob URL',
'            var blob = new Blob([fullHTMLDocument], { type: ''text/html;charset=utf-8;'' });',
'            var link = document.createElement("a");',
'            ',
'            if (link.download !== undefined) {',
'                var url = URL.createObjectURL(blob);',
'                link.setAttribute("href", url);',
'                link.setAttribute("download", customFileName);',
'                link.style.visibility = ''hidden'';',
'                document.body.appendChild(link);',
'                link.click();',
'                document.body.removeChild(link);',
'',
'                // Revoke Object URL to free memory',
'                setTimeout(function() {',
'                    URL.revokeObjectURL(url);',
'                }, 100);',
'            }',
'',
'        } else {',
'            // Invalid Output Type error',
'            apex.message.showErrors([{',
'                type:     "error",',
'                location: "page",',
'                message:  "Invalid Output Type selected. Allowed values: PDF, WORD, HTML.",',
'                unsafe:   false',
'            }]);',
'        }',
'',
'    } catch (err) {',
'        console.error("Export Error:", err);',
'        apex.message.showErrors([{',
'            type:     "error",',
'            location: "page",',
'            message:  "An error occurred during file export: " + err.message,',
'            unsafe:   false',
'        }]);',
'    }',
'}'))
,p_step_template=>4072355960268175073
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
);
