,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '// 1. Check karein ki library window scope me available hai ya nahi',
    'if (typeof htmlToPdfmake === ''undefined'' || typeof pdfMake === ''undefined'') {',
    '    apex.message.showErrors([{',
    '        type:       "error",',
    '        location:   "page",',
    '        message:    "PDF generation libraries load nahi ho payi. Kripya page refresh karke dobara try karein.",',
    '        unsafe:     false',
    '    }]);',
    '    return;',
    '}',
    '',
    '// 2. Rich Text Content aur File Name get karein',
    'var htmlContent = apex.item("P2_TEMPLATE_HTML").getValue();',
    'var customFileName = apex.item("P2_FILE_NAME").getValue();',
    '',
    'if (!customFileName || customFileName.trim() === "") {',
    '    customFileName = ''Document_'' + new Date().toISOString().slice(0,10);',
    '}',
    'if (!customFileName.toLowerCase().endsWith(''.pdf'')) {',
    '    customFileName += ''.pdf'';',
    '}',
    '',
    '// 3. Convert HTML to pdfMake JSON structure',
    'try {',
    '    var pdfContent = htmlToPdfmake(htmlContent, {',
    '        defaultStyles: {',
    '            b: { bold: true },',
    '            strong: { bold: true },',
    '            u: { decoration: ''underline'' },',
    '            s: { decoration: ''lineThrough'' },',
    '            i: { italics: true },',
    '            em: { italics: true }',
    '        }',
    '    });',
    '',
    '    // 4. Document Definition',
    '    var docDefinition = {',
    '        content: pdfContent,',
    '        pageMargins: [40, 60, 40, 60],',
    '        defaultStyle: {',
    '            fontSize: 11,',
    '            font: ''Roboto''',
    '        }',
    '    };',
    '',
    '    // 5. Download PDF',
    '    pdfMake.createPdf(docDefinition).download(customFileName);',
    '',
    '} catch (e) {',
    '    console.error("PDF Generation Error:", e);',
    '    apex.message.showErrors([{',
    '        type:       "error",',
    '        location:   "page",',
    '        message:    "PDF Generate karne me dikkat aayi: " + e.message,',
    '        unsafe:     false',
    '    }]);',
    '}')))).to_clob
);
