wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(22272702525597385955)
,p_event_id=>wwv_flow_imp.id(22272702442326385954)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '// 1. Check karein ki htmlDocx library load ho chuki hai',
    'if (typeof htmlDocx === ''undefined'' || typeof saveAs === ''undefined'') {',
    '    apex.message.showErrors([{',
    '        type:       "error",',
    '        location:   "page",',
    '        message:    "Word generation libraries load nahi ho payi. Page refresh karke dobara try karein.",',
    '        unsafe:     false',
    '    }]);',
    '    return;',
    '}',
    '',
    '// 2. Rich Text HTML Content aur File Name get karein',
    'var htmlContent = apex.item("P2_TEMPLATE_HTML").getValue();',
    'var customFileName = apex.item("P2_FILE_NAME").getValue();',
    '',
    '// File Name validation logic',
    'if (!customFileName || customFileName.trim() === "") {',
    '    customFileName = ''Document_'' + new Date().toISOString().slice(0,10);',
    '}',
    '',
    '// Ensure .docx extension',
    'if (customFileName.toLowerCase().endsWith(''.pdf'')) {',
    '    customFileName = customFileName.substring(0, customFileName.lastIndexOf(''.'')) + ''.docx'';',
    '} else if (!customFileName.toLowerCase().endsWith(''.docx'')) {',
    '    customFileName += ''.docx'';',
    '}',
    '',
    '// 3. Clean Full HTML Template banayein (CSS styling ke sath)',
    'var fullHTML = `',
    '    <!DOCTYPE html>',
    '    <html>',
    '    <head>',
    '        <meta charset="utf-8">',
    '        <style>',
    '            body { font-family: ''Calibri'', ''Arial'', sans-serif; font-size: 11pt; line-height: 1.5; }',
    '            table { border-collapse: collapse; width: 100%; margin-bottom: 10px; }',
    '            table, th, td { border: 1px solid #cccccc; padding: 6px; }',
    '            th { background-color: #f2f2f2; font-weight: bold; }',
    '            b, strong { font-weight: bold; }',
    '            i, em { font-style: italic; }',
    '            u { text-decoration: underline; }',
    '        </style>',
    '    </head>',
    '    <body>',
    '        ${htmlContent}',
    '    </body>',
    '    </html>',
    '`;',
    '',
    'try {',
    '    // 4. HTML ko .docx Blob format me convert karein',
    '    var convertedBlob = htmlDocx.asBlob(fullHTML, {',
    '        orientation: ''portrait'',',
    '        margins: { top: 720, right: 720, bottom: 720, left: 720 } // 0.5 inch margins in twips',
    '    });',
    '',
    '    // 5. Native .docx File Download karein',
    '    saveAs(convertedBlob, customFileName);',
    '',
    '} catch (e) {',
    '    console.error("Word Generation Error:", e);',
    '    apex.message.showErrors([{',
    '        type:       "error",',
    '        location:   "page",',
    '        message:    "Word document generate karne me dikkat aayi: " + e.message,',
    '        unsafe:     false',
    '    }]);',
    '}')))).to_clob
);
