wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(22272701334893385943)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_TEMPLATE_HTML'
,p_static_id=>'get-template-html'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html CLOB;',
'    l_amount INTEGER := 8000;',
'    l_offset INTEGER := 1;',
'    l_len    INTEGER;',
'    l_buffer VARCHAR2(32767);',
'BEGIN',
'    -- Fetch HTML Template into CLOB',
'    SELECT template_html',
'      INTO l_html',
'      FROM AOP_DEMO_LETTER_TEMPLATE_MASTER',
'     WHERE TEMPLATE_ID = :P2_TEMPLATE;',
'',
'    -- Fetch Employee Data',
'    FOR r IN (',
'        SELECT ',
'            EMP_CODE,',
'            FIRST_NAME,',
'            LAST_NAME,',
'            FIRST_NAME||'' ''||LAST_NAME AS FULL_NAME,',
'            EMAIL,',
'            MOBILE,',
'            GENDER,',
'            TO_CHAR(DOB,''DD-MON-YYYY'') AS DOB,',
'            DESIGNATION,',
'            DEPARTMENT,',
'            TO_CHAR(JOINING_DATE,''DD-MON-YYYY'') AS JOINING_DATE,',
'            EMPLOYMENT_TYPE,',
'            TO_CHAR(SALARY,''FM999G999G999D00'') AS SALARY,',
'            REPORTING_MANAGER,',
'            COMPANY_NAME,',
'            COMPANY_ADDRESS,',
'            COMPANY_EMAIL,',
'            COMPANY_PHONE,',
'            HR_NAME,',
'            STATUS,',
'            TO_CHAR(SYSDATE,''DD-MON-YYYY'') AS CURRENT_DATE',
'        FROM AOP_DEMO_EMPLOYEE_MASTER',
'        WHERE EMP_ID = :P2_EMP_ID',
'    )',
'    LOOP',
'        -- Replace placeholders safely in CLOB',
'        l_html := REPLACE(l_html, ''{EMP_CODE}'', r.EMP_CODE);',
'        l_html := REPLACE(l_html, ''{FIRST_NAME}'', r.FIRST_NAME);',
'        l_html := REPLACE(l_html, ''{LAST_NAME}'', r.LAST_NAME);',
'        l_html := REPLACE(l_html, ''{FULL_NAME}'', r.FULL_NAME);',
'        l_html := REPLACE(l_html, ''{EMAIL}'', r.EMAIL);',
'        l_html := REPLACE(l_html, ''{MOBILE}'', r.MOBILE);',
'        l_html := REPLACE(l_html, ''{GENDER}'', r.GENDER);',
'        l_html := REPLACE(l_html, ''{DOB}'', r.DOB);',
'        l_html := REPLACE(l_html, ''{DESIGNATION}'', r.DESIGNATION);',
'        l_html := REPLACE(l_html, ''{DEPARTMENT}'', r.DEPARTMENT);',
'        l_html := REPLACE(l_html, ''{JOINING_DATE}'', r.JOINING_DATE);',
'        l_html := REPLACE(l_html, ''{EMPLOYMENT_TYPE}'', r.EMPLOYMENT_TYPE);',
'        l_html := REPLACE(l_html, ''{SALARY}'', r.SALARY);',
'        l_html := REPLACE(l_html, ''{REPORTING_MANAGER}'', r.REPORTING_MANAGER);',
'        l_html := REPLACE(l_html, ''{COMPANY_NAME}'', r.COMPANY_NAME);',
'        l_html := REPLACE(l_html, ''{COMPANY_ADDRESS}'', r.COMPANY_ADDRESS);',
'        l_html := REPLACE(l_html, ''{COMPANY_EMAIL}'', r.COMPANY_EMAIL);',
'        l_html := REPLACE(l_html, ''{COMPANY_PHONE}'', r.COMPANY_PHONE);',
'        l_html := REPLACE(l_html, ''{HR_NAME}'', r.HR_NAME);',
'        l_html := REPLACE(l_html, ''{STATUS}'', r.STATUS);',
'        l_html := REPLACE(l_html, ''{CURRENT_DATE}'', r.CURRENT_DATE);',
'    END LOOP;',
'',
'    -- Output large CLOB safely in chunks to avoid HTP buffer overflow',
'    l_len := DBMS_LOB.GETLENGTH(l_html);',
'    ',
'    WHILE l_offset <= l_len LOOP',
'        l_buffer := DBMS_LOB.SUBSTR(l_html, l_amount, l_offset);',
'        HTP.P(l_buffer);',
'        l_offset := l_offset + l_amount;',
'    END LOOP;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(''Error: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>200748889734079636
);
end;
