begin
wwv_flow_imp_page.create_page(
 p_id=>5
,p_name=>'Letter Template'
,p_alias=>'LETTER-TEMPLATE'
,p_page_mode=>'MODAL'
,p_step_title=>'Letter Template'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-------------------------  CDN Link ------------------------------',
'',
'-- https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js',
'-- https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.min.js',
'-- https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js',
'',
'',
'',
'------------------------- CDN Static File -------------------------------',
'',
'#APP_FILES#mammoth.browser.min.js',
'#APP_FILES#pdf.min.js',
'#APP_FILES#jszip.min.js'))
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/**',
' * Converts uploaded Document (.docx, .pdf, .pptx) into HTML string',
' * and sets the target APEX Page Item value using Local Static Files.',
' * ',
' * @param {string} fileInputId - Item ID of File Browse (e.g., ''P5_TEMPLATE_FILE'')',
' * @param {string} targetItemId - Item ID of Target HTML Item (e.g., ''P5_TEMPLATE_HTML'')',
' */',
'function convertDocumentToHtml(fileInputId, targetItemId) {',
'    // Configure PDF.js worker using APEX Static File path reference',
'    pdfjsLib.GlobalWorkerOptions.workerSrc = ''&APP_FILES.pdf.worker.min.js'';',
'',
'    // // Configure PDF.js worker URL',
'    // pdfjsLib.GlobalWorkerOptions.workerSrc = ''https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.worker.min.js'';',
'',
'    var fileInput = document.getElementById(fileInputId);',
'',
'    if (fileInput && fileInput.files && fileInput.files[0]) {',
'        var file = fileInput.files[0];',
'        var fileName = file.name.toLowerCase();',
'        var reader = new FileReader();',
'',
'        // -------------------------------------------------------------',
'        // 1. WORD DOCUMENT (.docx) CONVERSION',
'        // -------------------------------------------------------------',
'        if (fileName.endsWith(''.docx'')) {',
'            reader.onload = function(loadEvent) {',
'                mammoth.convertToHtml({ arrayBuffer: loadEvent.target.result })',
'                    .then(function(result) {',
'                        $s(targetItemId, result.value);',
'                    })',
'                    .catch(function(err) {',
'                        console.error(''Word Conversion Error: '', err);',
'                    });',
'            };',
'            reader.readAsArrayBuffer(file);',
'        }  ',
'        // -------------------------------------------------------------',
'        // 2. PDF DOCUMENT (.pdf) CONVERSION',
'        // -------------------------------------------------------------',
'        else if (fileName.endsWith(''.pdf'')) {',
'            reader.onload = function(loadEvent) {',
'                var typedarray = new Uint8Array(loadEvent.target.result);',
'                ',
'                pdfjsLib.getDocument(typedarray).promise.then(function(pdf) {',
'                    var totalPages = pdf.numPages;',
'                    var countPromises = [];',
'',
'                    for (var i = 1; i <= totalPages; i++) {',
'                        countPromises.push(',
'                            pdf.getPage(i).then(function(page) {',
'                                return page.getTextContent().then(function(textContent) {',
'                                    var lastY = null;',
'                                    var pageHtml = ''<div class="pdf-page">'';',
'',
'                                    // Iterate through text items and calculate line gaps based on Y-coordinates',
'                                    textContent.items.forEach(function(item) {',
'                                        var currentY = item.transform[5]; // Y-axis position',
'                                        ',
'                                        if (lastY !== null) {',
'                                            var lineGap = Math.abs(lastY - currentY);',
'                                            ',
'                                            if (lineGap > 12) { ',
'                                                // Large gap indicates a new paragraph',
'                                                pageHtml += ''</p><p>'';',
'                                            } else if (lineGap > 2) { ',
'                                                // Small gap indicates a new line in the same paragraph',
'                                                pageHtml += ''<br/>'';',
'                                            }',
'                                        } else {',
'                                            pageHtml += ''<p>'';',
'                                        } ',
'',
'                                        pageHtml += item.str;',
'                                        lastY = currentY;',
'                                    });     ',
'',
'                                    pageHtml += ''</p></div>'';',
'                                    return pageHtml;',
'                                });',
'                            })',
'                        );',
'                    }',
'',
'                    Promise.all(countPromises).then(function(pagesHtml) {',
'                        var finalHtml = pagesHtml.join('''');',
'                        $s(targetItemId, finalHtml);',
'                    });',
'                }).catch(function(err) {',
'                    console.error(''PDF Conversion Error: '', err);',
'                });',
'            };',
'            reader.readAsArrayBuffer(file);',
'        }',
'        // -------------------------------------------------------------',
'        // 3. POWERPOINT PRESENTATION (.pptx) CONVERSION',
'        // -------------------------------------------------------------',
'        else if (fileName.endsWith(''.pptx'')) {',
'            reader.onload = function(loadEvent) {',
'                JSZip.loadAsync(loadEvent.target.result).then(function(zip) {',
'                    // Filter slide XML files from PPTX package',
'                    var slideFiles = Object.keys(zip.files).filter(function(name) {',
'                        return name.startsWith(''ppt/slides/slide'') && name.endsWith(''.xml'');',
'                    });',
'',
'                    // Sort slides numerically by slide index',
'                    slideFiles.sort(function(a, b) {',
'                        var numA = parseInt(a.match(/\d+/)[0]);',
'                        var numB = parseInt(b.match(/\d+/)[0]);',
'                        return numA - numB;',
'                    });',
'',
'                    var slidePromises = slideFiles.map(function(slidePath) {',
'                        return zip.files[slidePath].async(''string'').then(function(xmlText) {',
'                            var parser = new DOMParser();',
'                            var xmlDoc = parser.parseFromString(xmlText, ''text/xml'');',
'                            ',
'                            // Retrieve all paragraph tags (''a:p'') in slide',
'                            var paragraphs = xmlDoc.getElementsByTagName(''a:p'');',
'                            var slideHtml = ''<div class="ppt-slide">'';',
'',
'                            for (var i = 0; i < paragraphs.length; i++) {',
'                                var p = paragraphs[i];',
'                                var pText = '''';',
'',
'                                // Parse text nodes (''a:t'') and line break nodes (''a:br'')',
'                                var children = p.getElementsByTagName(''*'');',
'                                for (var j = 0; j < children.length; j++) {',
'                                    var node = children[j];',
'',
'                                    if (node.tagName === ''a:t'') {',
'                                        pText += node.textContent;',
'                                    } else if (node.tagName === ''a:br'') {',
'                                        pText += ''<br/>'';',
'                                    }',
'                                }',
'',
'                                if (pText.trim().length > 0) {',
'                                    slideHtml += ''<p>'' + pText + ''</p>'';',
'                                }',
'                            }',
'',
'                            slideHtml += ''</div>'';',
'                            return slideHtml;',
'                        });',
'                    });',
'',
'                    Promise.all(slidePromises).then(function(slidesHtml) {',
'                        var finalHtml = slidesHtml.join('''');',
'                        $s(targetItemId, finalHtml);',
'                    });',
'                }).catch(function(err) {',
'                    console.error(''PPTX Conversion Error: '', err);',
'                });',
'            };',
'            reader.readAsArrayBuffer(file);',
'        }',
'        // -------------------------------------------------------------',
'        // UNSUPPORTED FILE FORMAT ERROR HANDLING',
'        // -------------------------------------------------------------',
'        else {',
'            apex.message.showErrors([',
'                {',
'                    type: "error",',
'                    location: "page",',
'                    message: "Please upload a valid Word (.docx), PDF (.pdf), or PowerPoint (.pptx) file.",',
'                    unsafe: false',
'                }',
'            ]);',
'        }',
'    }',
'}'))
