wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(22272700636684385936)
,p_event_id=>wwv_flow_imp.id(22316838126409303534)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_submit', 'P8_TEMPLATE_HTML,P8_TEMPLATE',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '-- UPDATE AOP_DEMO_LETTER_TEMPLATE_MASTER',
    '-- SET TEMPLATE_HTML = :P8_TEMPLATE_HTML',
    '-- WHERE TEMPLATE_ID = :P8_TEMPLATE;',
    'DECLARE',
    '    l_blob         BLOB;',
    '    l_dest_offset  INTEGER := 1;',
    '    l_src_offset   INTEGER := 1;',
    '    l_lang_context INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;',
    '    l_warning      INTEGER;',
    'BEGIN',
    '    DBMS_LOB.CREATETEMPORARY(l_blob, TRUE);',
    '',
    '    DBMS_LOB.CONVERTTOBLOB(',
    '        dest_lob     => l_blob,',
    '        src_clob     => :P8_TEMPLATE_HTML,',
    '        amount       => DBMS_LOB.LOBMAXSIZE,',
    '        dest_offset  => l_dest_offset,',
    '        src_offset   => l_src_offset,',
    '        blob_csid    => DBMS_LOB.DEFAULT_CSID,',
    '        lang_context => l_lang_context,',
    '        warning      => l_warning',
    '    );',
    '',
    '    UPDATE AOP_DEMO_LETTER_TEMPLATE_MASTER',
    '       SET TEMPLATE_HTML = :P8_TEMPLATE_HTML,',
    '           TEMPLATE_FILE = l_blob,',
    '           FILE_NAME     = ''EditedTemplate.html'',',
    '           MIME_TYPE     = ''text/html''',
    '     WHERE TEMPLATE_ID = :P8_TEMPLATE;',
    'END;')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
);
