'--            SELECT',
'--     LOWER(SUBSTR(FILE_NAME, INSTR(FILE_NAME,''.'',-1)+1)) AS TEMPLATE_TYPE,',
'--     TEMPLATE_FILE',
'-- FROM AOP_DEMO_LETTER_TEMPLATE_MASTER',
'-- WHERE TEMPLATE_ID = :P8_TEMPLATE;',
'--     !'';',
'',
'',
'',
'--     ------------------------------------------------------------------',
'--     -- 2. Dynamic Data Source',
'--     ------------------------------------------------------------------',
'--     l_data_source := q''!',
'--         SELECT',
'--             ''Appointment_Letter_'' || EMP_CODE AS "filename",',
'--             CURSOR (',
'--                 SELECT',
'--                     CURSOR (',
'--                         SELECT',
'--                             EMP_CODE                            AS "EMP_CODE",',
'--                             FIRST_NAME                          AS "FIRST_NAME",',
'--                             LAST_NAME                           AS "LAST_NAME",',
'--                             FIRST_NAME || '' '' || LAST_NAME      AS "FULL_NAME",',
'--                             EMAIL                               AS "EMAIL",',
'--                             MOBILE                              AS "MOBILE",',
'--                             GENDER                              AS "GENDER",',
'--                             TO_CHAR(DOB,''DD-MON-YYYY'')          AS "DOB",',
'--                             DESIGNATION                         AS "DESIGNATION",',
'--                             DEPARTMENT                          AS "DEPARTMENT",',
'--                             TO_CHAR(JOINING_DATE,''DD-MON-YYYY'') AS "JOINING_DATE",',
'--                             EMPLOYMENT_TYPE                     AS "EMPLOYMENT_TYPE",',
'--                             TO_CHAR(SALARY,''FM999G999G999D00'') AS "SALARY",',
'--                             REPORTING_MANAGER                   AS "REPORTING_MANAGER",',
'--                             COMPANY_NAME                        AS "COMPANY_NAME",',
'--                             COMPANY_ADDRESS                     AS "COMPANY_ADDRESS",',
'--                             COMPANY_EMAIL                       AS "COMPANY_EMAIL",',
'--                             COMPANY_PHONE                       AS "COMPANY_PHONE",',
'--                             HR_NAME                             AS "HR_NAME",',
'--                             STATUS                              AS "STATUS",',
'--                             TO_CHAR(SYSDATE,''DD-MON-YYYY'')      AS "CURRENT_DATE"',
'--                         FROM AOP_DEMO_EMPLOYEE_MASTER',
'--                         WHERE EMP_ID = :P8_EMP_ID',
'--                     ) AS "employee"',
'--                 FROM DUAL',
'--             ) AS "data"',
'--         FROM AOP_DEMO_EMPLOYEE_MASTER',
'--         WHERE EMP_ID = :P8_EMP_ID',
'--     !'';',
