'--                     p_output_filename => :P8_FILE_NAME,',
'--                     p_binds           => l_binds,',
'--                     p_aop_url         => ''https://api.apexofficeprint.com'',',
'--                     p_api_key         => ''57BC88E058D0EC0AE0637203000AED21'',',
'--                     p_app_id          => :APP_ID,',
'--                     p_page_id         => :PAGE_ID);',
'',
'--     ------------------------------------------------------------------',
'--     -- 4. Direct Download Response',
'--     ------------------------------------------------------------------',
'--     l_file_name := NVL(:P8_FILE_NAME, ''Appointment_Letter_'' || :P8_EMP_ID) || ''.docx'';',
'',
'--     htp.init;',
'--     sys.owa_util.mime_header(''application/vnd.openxmlformats-officedocument.wordprocessingml.document'', FALSE);',
'--     htp.p(''Content-Length: '' || dbms_lob.getlength(l_return));',
