'-- end;',
'',
'',
'',
'',
'',
'',
'',
'declare',
'    l_binds           wwv_flow_plugin_util.t_bind_list;',
'    l_return          blob;',
'    l_data_source     clob;',
'    l_template_source clob;',
'    l_file_name       varchar2(255);',
'    l_mime_type       varchar2(150);',
'    l_output_type     varchar2(10);',
'begin',
'    l_output_type := LOWER(NVL(:P8_OUTPUT_TYPE, ''docx''));',
'    -- l_output_type := LOWER(:P8_OUTPUT_TYPE);',
'',
'    ------------------------------------------------------------------',
'    -- 1. Dynamic Template Source',
'    ------------------------------------------------------------------',
'    l_template_source := q''!',
'        SELECT',
'            LOWER(SUBSTR(FILE_NAME, INSTR(FILE_NAME, ''.'', -1) + 1)) AS TEMPLATE_TYPE,',
'            TEMPLATE_FILE',
'        FROM AOP_DEMO_LETTER_TEMPLATE_MASTER',
