'                            MOBILE                              AS "MOBILE",',
'                            GENDER                              AS "GENDER",',
'                            TO_CHAR(DOB,''DD-MON-YYYY'')          AS "DOB",',
'                            DESIGNATION                         AS "DESIGNATION",',
'                            DEPARTMENT                          AS "DEPARTMENT",',
'                            TO_CHAR(JOINING_DATE,''DD-MON-YYYY'') AS "JOINING_DATE",',
'                            EMPLOYMENT_TYPE                     AS "EMPLOYMENT_TYPE",',
'                            TO_CHAR(SALARY,''FM999G999G999D00'') AS "SALARY",',
'                            REPORTING_MANAGER                   AS "REPORTING_MANAGER",',
'                            COMPANY_NAME                        AS "COMPANY_NAME",',
'                            COMPANY_ADDRESS                     AS "COMPANY_ADDRESS",',
'                            COMPANY_EMAIL                       AS "COMPANY_EMAIL",',
'                            COMPANY_PHONE                       AS "COMPANY_PHONE",',
'                            HR_NAME                             AS "HR_NAME",',
'                            STATUS                              AS "STATUS",',
'                            TO_CHAR(SYSDATE,''DD-MON-YYYY'')      AS "CURRENT_DATE"',
'                        FROM AOP_DEMO_EMPLOYEE_MASTER',
'                        WHERE EMP_ID = :P8_EMP_ID',
'                    ) AS "employee"',
'                FROM DUAL',
'            ) AS "data"',
'        FROM AOP_DEMO_EMPLOYEE_MASTER',
'        WHERE EMP_ID = :P8_EMP_ID',
'    !'';',
'',
'    ------------------------------------------------------------------',
'    -- 3. Call AOP API (Dynamic p_output_type)',
'    ------------------------------------------------------------------',
'    l_return := aop_api_pkg.plsql_call_to_aop (',
'                    p_data_type       => aop_api_pkg.c_source_type_sql,',
'                    p_data_source     => l_data_source,',
'                    p_template_type   => aop_api_pkg.c_source_type_sql,',
'                    p_template_source => l_template_source,',
'                    p_output_type     => l_output_type, -- <-- Here: Dynamic Format from LOV',
'                    p_output_filename => :P8_FILE_NAME,',
'                    p_binds           => l_binds,',
'                    p_aop_url         => ''https://api.apexofficeprint.com'',',
'                    p_api_key         => ''57BC88E058D0EC0AE0637203000AED21'',',
'                    p_app_id          => :APP_ID,',
'                    p_page_id         => :PAGE_ID);',
'',
'    ------------------------------------------------------------------',
'    -- 4. Dynamic MIME Type and Extension Mapping',
'    ------------------------------------------------------------------',
'    case l_output_type',
'        when ''pdf'' then',
'            l_mime_type := ''application/pdf'';',
'        when ''html'' then',
'            l_mime_type := ''text/html'';',
'        else -- Default ''docx''',
'            l_mime_type := ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'';',
'    end case;',
'',
'    -- Dynamic Filename with correct extension',
'    l_file_name := NVL(:P8_FILE_NAME, ''Appointment_Letter_'' || :P8_EMP_ID) || ''.'' || l_output_type;',
'',
'    ------------------------------------------------------------------',
'    -- 5. Direct Download Response',
'    ------------------------------------------------------------------',
'    htp.init;',
'    sys.owa_util.mime_header(l_mime_type, FALSE);',
'    htp.p(''Content-Length: '' || dbms_lob.getlength(l_return));',
'    htp.p(''Content-Disposition: attachment; filename="'' || l_file_name || ''"'');',
'    sys.owa_util.http_header_close;',
'',
'    wpg_docload.download_file(l_return);',
'    apex_application.stop_apex_engine;',
'',
'exception',
'    when apex_application.e_stop_apex_engine then',
'        null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>248237151818316017
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(22320189170198622320)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generate AOP Async URL'
,p_static_id=>'generate-aop-async-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_binds           wwv_flow_plugin_util.t_bind_list;',
'  l_return          blob;',
'  l_data_source       CLOB;',
'  l_template_source   CLOB;',
'  l_file_name       varchar2(255);',
'begin',
'  -- set the output to JSON, so we see what is being sent to the AOP Server (uncomment next line)',
'  -- aop_api_pkg.g_debug := ''Local'';',
'  -- set output to own custom debug table (uncomment next line)',
'  -- aop_api_pkg.g_debug_procedure := ''aop_sample_pkg.custom_debug'';',
'  --',
'  -- most minimalistic example ',
'------------------------------------------------------------------',
'    -- 1. Dynamic Template Source (HTML from Page Item)',
'    ------------------------------------------------------------------',
'    l_template_source := q''!',
'        SELECT',
'            ''html'' AS template_type,',
'            APEX_UTIL.CLOB_TO_BLOB(:P8_TEMPLATE_HTML_1) AS template_file',
'        FROM dual',
'    !'';',
'',
'    ------------------------------------------------------------------',
'    -- 2. Dynamic Data Source (Your Exact Employee Query)',
'    ------------------------------------------------------------------',
'    l_data_source := q''!',
'        SELECT',
'            ''Appointment_Letter_'' || EMP_CODE AS "filename",',
'            CURSOR (',
'                SELECT',
'                    CURSOR (',
'                        SELECT',
'                            EMP_CODE                           AS "EMP_CODE",',
'                            FIRST_NAME                         AS "FIRST_NAME",',
'                            LAST_NAME                          AS "LAST_NAME",',
'                            FIRST_NAME || '' '' || LAST_NAME     AS "FULL_NAME",',
'                            EMAIL                              AS "EMAIL",',
'                            MOBILE                             AS "MOBILE",',
'                            GENDER                             AS "GENDER",',
'                            TO_CHAR(DOB,''DD-MON-YYYY'')         AS "DOB",',
'                            DESIGNATION                        AS "DESIGNATION",',
'                            DEPARTMENT                         AS "DEPARTMENT",',
'                            TO_CHAR(JOINING_DATE,''DD-MON-YYYY'') AS "JOINING_DATE",',
'                            EMPLOYMENT_TYPE                    AS "EMPLOYMENT_TYPE",',
'                            TO_CHAR(SALARY,''FM999G999G999D00'') AS "SALARY",',
'                            REPORTING_MANAGER                  AS "REPORTING_MANAGER",',
'                            COMPANY_NAME                       AS "COMPANY_NAME",',
'                            COMPANY_ADDRESS                    AS "COMPANY_ADDRESS",',
'                            COMPANY_EMAIL                      AS "COMPANY_EMAIL",',
'                            COMPANY_PHONE                      AS "COMPANY_PHONE",',
'                            HR_NAME                            AS "HR_NAME",',
'                            STATUS                             AS "STATUS",',
'                            TO_CHAR(SYSDATE,''DD-MON-YYYY'')     AS "CURRENT_DATE"',
'                        FROM AOP_DEMO_EMPLOYEE_MASTER',
'                        WHERE EMP_ID = :P8_EMP_ID',
'                    ) AS "employee"',
'                FROM DUAL',
'            ) AS "data"',
'        FROM AOP_DEMO_EMPLOYEE_MASTER',
'        WHERE EMP_ID = :P8_EMP_ID',
'    !'';',
'  l_return := aop_api_pkg.plsql_call_to_aop (',
'                p_data_type       => aop_api_pkg.c_source_type_sql,',
'                p_data_source     => l_data_source,',
'                p_template_type   => aop_api_pkg.c_source_type_sql,',
'                p_template_source => l_template_source,',
'                p_output_type     => ''docx'',',
'                p_output_filename => :P8_FILE_NAME,',
'                p_binds           => l_binds,',
'                p_aop_url         => ''https://api.apexofficeprint.com'',',
'                p_api_key         => ''5706EDFFFF795705E0637203000AF5B4'', -- change the API key if you use the AOP Cloud',
'                p_app_id          => :APP_ID,              -- change to APEX app id',
'                p_page_id         => :PAGE_ID);             -- change to APEX page id',
'  ',
'  -- write output to table (uncomment next line)',
'--   insert into aop_output (output_blob, filename) values (l_return, :P8_FILE_NAME);              ',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(22320189418375622322)
