wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(22316839466315303548)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE TEMPLATE'
,p_static_id=>'save-template'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- UPDATE AOP_DEMO_LETTER_TEMPLATE_MASTER',
'-- SET TEMPLATE_HTML = :P8_TEMPLATE_HTML',
'-- WHERE TEMPLATE_ID = :P8_TEMPLATE;',
'DECLARE',
'    l_blob         BLOB;',
'    l_dest_offset  INTEGER := 1;',
'    l_src_offset   INTEGER := 1;',
'    l_lang_context INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;',
'    l_warning      INTEGER;',
'BEGIN',
'    DBMS_LOB.CREATETEMPORARY(l_blob, TRUE);',
'',
'    DBMS_LOB.CONVERTTOBLOB(',
'        dest_lob     => l_blob,',
'        src_clob     => :P8_TEMPLATE_HTML,',
'        amount       => DBMS_LOB.LOBMAXSIZE,',
'        dest_offset  => l_dest_offset,',
'        src_offset   => l_src_offset,',
'        blob_csid    => DBMS_LOB.DEFAULT_CSID,',
'        lang_context => l_lang_context,',
'        warning      => l_warning',
'    );',
'',
'    UPDATE AOP_DEMO_LETTER_TEMPLATE_MASTER',
'       SET TEMPLATE_HTML = :P8_TEMPLATE_HTML,',
'           TEMPLATE_FILE = l_blob,',
'           FILE_NAME     = ''EditedTemplate.html'',',
'           MIME_TYPE     = ''text/html''',
'     WHERE TEMPLATE_ID = :P8_TEMPLATE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(22316839375940303547)
,p_process_when_type=>'NEVER'
,p_internal_uid=>244887021155997241
);
end;
